//! Hysj desktop app: a Tauri window around the web UI in `ui/`.
//!
//! The daemon owns mail, the store and the models; this process is a normal
//! `hysjd` client. The UI gets typed commands (one per daemon call, types from
//! `hysj-proto`, TypeScript generated by ts-rs), hears "something changed" as a
//! `changed` event, and asks Rust — never the webview — to open links.

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

mod update;

use std::time::Duration;

use hysj_core::{Client, ClientError};
use hysj_proto::{
    Account, AccountAddParams, AttachmentData, AttachmentParams, BookingItem, Bucket, CodeItem,
    CodeReport, CodeSettings, Contact, Decision, Folder, FolderParams, Identity, IdentitySuggest,
    IdentitySuggestion, ListParams, Message, MessageDone, MessageSummary, MessageView, OrderItem,
    ScreenerDecide, ScreenerDecided, ScreenerForget, SendParams, SendResult, SenderImages,
    ShowParams, SyncParams, SyncResult, method,
};
use hysjd::socket::SocketTransport;
use serde::{Serialize, de::DeserializeOwned};
use tauri::{Emitter, State};
use tokio::sync::Mutex;

/// The UI's connection to the daemon, as kind "app" (so the daemon knows a
/// window is open and leaves code pop-ups to it).
struct Bridge(Mutex<Option<Client<SocketTransport>>>);

type Res<T> = Result<T, String>;

impl Bridge {
    /// One call; reconnects (starting the daemon if needed) when the old one
    /// went away, e.g. after a rebuild.
    async fn call<R: DeserializeOwned>(&self, method: &str, params: impl Serialize) -> Res<R> {
        let mut slot = self.0.lock().await;
        for attempt in 0..2 {
            if slot.is_none() {
                *slot = Some(
                    hysjd::socket::client(Some("app"))
                        .await
                        .map_err(|e| e.to_string())?,
                );
            }
            let client = slot.as_mut().expect("connected above");
            match client.call::<R>(method, &params).await {
                Ok(v) => return Ok(v),
                Err(ClientError::Closed(_)) if attempt == 0 => *slot = None,
                Err(e) => return Err(e.to_string()),
            }
        }
        Err("could not reach the mail engine".into())
    }
}

