/// A file name that stays a file name: no folders, no hidden files, no
/// control characters, not too long.
fn safe_file_name(name: &str) -> String {
    let cleaned: String = name
        .chars()
        .map(|c| {
            if c.is_control() || "/\\:*?\"<>|".contains(c) {
                '_'
            } else {
                c
            }
        })
        .collect();
    let trimmed = cleaned.trim().trim_start_matches('.').trim();
    let mut out: String = trimmed
        .chars()
        .rev()
        .take(120)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    if out.is_empty() {
        out = "attachment".into();
    }
    out
}

/// Types that open in a viewer, never run. Anything else is shown in Finder.
fn opens_safely(name: &str) -> bool {
    let ext = name
        .rsplit_once('.')
        .map(|(_, e)| e.to_ascii_lowercase())
        .unwrap_or_default();
    [
        "pdf", "png", "jpg", "jpeg", "gif", "webp", "heic", "tif", "tiff", "txt", "csv", "ics",
        "vcf", "eml", "rtf", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "odt", "ods", "odp",
        "pages", "numbers", "key", "mp3", "m4a", "mp4", "mov",
        // Wallet passes: Wallet checks the pass's signature before adding it.
        "pkpass",
    ]
    .contains(&ext.as_str())
}

/// Saves an attachment to Downloads (never overwriting), then opens it if
/// that's safe, else reveals it in Finder. Returns where it went.
#[tauri::command]
async fn attachment_save(b: State<'_, Bridge>, id: String, index: u32, open: bool) -> Res<String> {
    use base64::Engine;
    let a: AttachmentData = b
        .call(method::MESSAGE_ATTACHMENT, AttachmentParams { id, index })
        .await?;
    let data = base64::engine::general_purpose::STANDARD
        .decode(a.data)
        .map_err(|e| e.to_string())?;
    let dir = dirs::download_dir().ok_or("no Downloads folder")?;
    let name = safe_file_name(&a.name);
    let (stem, ext) = match name.rsplit_once('.') {
        Some((s, e)) if !s.is_empty() => (s.to_string(), format!(".{e}")),
        _ => (name.clone(), String::new()),
    };
    let mut path = dir.join(&name);
    let mut n = 2;
    while path.exists() {
        path = dir.join(format!("{stem} ({n}){ext}"));
        n += 1;
    }
    std::fs::write(&path, data).map_err(|e| e.to_string())?;
    if cfg!(target_os = "macos") {
        let mut cmd = std::process::Command::new("open");
        if !(open && opens_safely(&name)) {
            cmd.arg("-R");
        }
        cmd.arg(&path).spawn().map_err(|e| e.to_string())?;
    }
    Ok(path.display().to_string())
}

/// Who an address belongs to: how it signs in and its servers.
#[tauri::command]
async fn account_discover(b: State<'_, Bridge>, address: String) -> Res<hysj_proto::ProviderInfo> {
    b.call(
        method::ACCOUNT_DISCOVER,
        hysj_proto::AccountOAuth { address },
    )
    .await
}

/// "Sign in with …" (Outlook.com, Hotmail): opens the provider's page in the
/// browser and waits until the person has signed in, on a connection of its
/// own so the rest of the app keeps working meanwhile.
#[tauri::command]
async fn account_oauth(address: String) -> Res<Account> {
    let mut own = hysjd::socket::client(Some("app"))
        .await
        .map_err(|e| e.to_string())?;
    let p = hysj_proto::AccountOAuth { address };
    let started: hysj_proto::OAuthStarted = own
        .call(method::ACCOUNT_OAUTH_START, &p)
        .await
        .map_err(|e| e.to_string())?;
    open_link(started.url)?;
    own.call(method::ACCOUNT_OAUTH_FINISH, &p)
        .await
        .map_err(|e| e.to_string())
}

/// Opens a link in the system browser. Only web links: the UI asks, Rust checks.
#[tauri::command]
fn open_link(url: String) -> Res<()> {
    let lower = url.trim().to_ascii_lowercase();
    if !(lower.starts_with("https://") || lower.starts_with("http://")) {
        return Err("only web links open from Hysj".into());
    }
    let opener = if cfg!(target_os = "macos") {
        "open"
    } else {
        "xdg-open"
    };
    std::process::Command::new(opener)
        .arg(url.trim())
        .spawn()
        .map(|_| ())
        .map_err(|e| e.to_string())
}

/// Turns the daemon's change pushes into `changed` events for the UI, and
/// keeps listening across daemon restarts.
async fn forward_changes(app: tauri::AppHandle) {
    loop {
        match hysjd::socket::client(None).await {
            Ok(mut events) => {
                let _ = app.emit("changed", ());
                while events.next_event().await.is_ok() {
                    let _ = app.emit("changed", ());
                }
            }
            Err(e) => tracing::warn!(error = %e, "no daemon events; retrying"),
        }
        tokio::time::sleep(Duration::from_secs(1)).await;
    }
}

fn main() {
    hysjd::run_if_daemon();
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .with_writer(std::io::stderr)
        .init();
    tauri::Builder::default()
        .plugin(tauri_plugin_updater::Builder::new().build())
        .manage(Bridge(Mutex::new(None)))
        .manage(update::Pending::default())
        .invoke_handler(tauri::generate_handler![
            ask,
            cleanup,
            unsubscribe,
            cleanup_keep,
            pile_archive,
            account_list,
            identity_list,
            contact_list,
            list,
            folder_list,
            show,
            code_list,
            code_settings,
            signal_list,
            digest_set,
            digest_hours,
            kind_correct,
            ai_settings,
            app_version,
            system_info,
            update_status,
            update_check,
            update_auto,
            update_restart,
            account_label,
            account_oauth,
            account_discover,
            signal_hold,
            booking_list,
            order_list,
            identity_suggest,
            screener_decide,
            screener_forget,
            message_done,
            message_restore,
            code_report,
            send,
            sync,
            account_add,
            message_view,
            digest_edition,
            search,
            sender_images,
            attachment_save,
            open_link,
        ])
        .setup(|app| {
            tauri::async_runtime::spawn(forward_changes(app.handle().clone()));
            tauri::async_runtime::spawn(update::background(app.handle().clone()));
            Ok(())
        })
        .build(tauri::generate_context!())
        .expect("Hysj window")
        .run(|app, event| {
            // "When I quit": a downloaded update installs on the way out.
            if let tauri::RunEvent::Exit = event {
                update::install(app);
            }
        });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn attachment_names() {
        assert_eq!(safe_file_name("../../etc/passwd"), "_.._etc_passwd");
        assert_eq!(safe_file_name(".hidden.sh"), "hidden.sh");
        assert_eq!(safe_file_name("  "), "attachment");
        assert_eq!(safe_file_name("Faktura oktober.pdf"), "Faktura oktober.pdf");
        assert!(opens_safely("Faktura.PDF"));
        for bad in [
            "run.command",
            "x.app",
            "a.sh",
            "b.pkg",
            "c.jar",
            "d.terminal",
            "e.zip",
            "noext",
        ] {
            assert!(!opens_safely(bad), "{bad}");
        }
    }
}
